import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.BWTY_seE.js";const g=JSON.parse('{"title":"AI 动态 · 2026-11-19","description":"","frontmatter":{"title":"AI 动态 · 2026-11-19","date":"2026-11-19T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-19.md","filePath":"news/2026-11/ai-news-2026-11-19.md","lastUpdated":null}'),i={name:"news/2026-11/ai-news-2026-11-19.md"};function s(o,e,l,c,p,h){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-19" tabindex="-1">AI 动态 · 2026-11-19 <a class="header-anchor" href="#ai-动态-·-2026-11-19" aria-label="Permalink to &quot;AI 动态 · 2026-11-19&quot;">​</a></h1><blockquote><p>截至 2026-11-19。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>Anthropic 完成史上最大 IPO，募资规模在 81.3 亿至 1070 亿美元区间，AI 融资循环与安全叙事同时接受市场检验。</li><li>Google 发布 Gemini 4 Neon，以 1M 上下文、AA Coding Agent Index 第一和更低 API 价格切入编码与分析场景，模型价格战继续。</li><li>Nvidia 在黄仁勋离任后由 Colette Kress 出任临时 CEO，微软与马斯克先后表态力挺，芯片与算力格局进入新阶段。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-anthropic-完成史上最大-ipo-募资-813-亿美元" tabindex="-1">头条 · Anthropic 完成史上最大 IPO，募资 813 亿美元 <a class="header-anchor" href="#头条-·-anthropic-完成史上最大-ipo-募资-813-亿美元" aria-label="Permalink to &quot;头条 · Anthropic 完成史上最大 IPO，募资 813 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/52e7e7b01b35.jpg" alt="配图"></p><p>Anthropic 今日完成筹备多年的 IPO，募资 813 亿美元，超越 SpaceX 成为史上规模最大的 IPO，也为后续上市的 AI 实验室立下先例。公司以「安全优先」起家，但高管强调只有跑在第一才能兑现使命，这需要大量资金与算力。对读者：关注其招股书中的算力承诺与安全投入比例，这是判断 AI 公司估值逻辑能否成立的关键样本。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1037459/anthropic-ipo-safe-ai-reputation-power-structure" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-千亿美元-ipo-背后-最大敌人是自己" tabindex="-1">Anthropic 千亿美元 IPO 背后：最大敌人是自己 <a class="header-anchor" href="#anthropic-千亿美元-ipo-背后-最大敌人是自己" aria-label="Permalink to &quot;Anthropic 千亿美元 IPO 背后：最大敌人是自己&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/0acc18f365b5.jpg" alt="配图"></p><p>Wired 指出，押注 1070 亿美元的投资者将权衡两件事：Anthropic 的 AI 安全战略，以及公众对数据中心日益增长的不满是否会影响其增长。对读者：若持有或计划参与 AI 基础设施相关标的，需把「社会许可」纳入风险清单，而不只看模型能力。</p><p class="news-entry-source"><a href="https://www.wired.com/story/anthropics-record-breaking-ipo-highlights-the-ai-giants-worst-enemy-itself/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-ipo-考验-ai-循环融资模式" tabindex="-1">Anthropic IPO 考验 AI 循环融资模式 <a class="header-anchor" href="#anthropic-ipo-考验-ai-循环融资模式" aria-label="Permalink to &quot;Anthropic IPO 考验 AI 循环融资模式&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d9cb12f8a034.jpg" alt="配图"></p><p>TechCrunch 分析称，Anthropic 上市后背负巨额算力承诺，但其最大基础设施伙伴亚马逊和谷歌即便在 Anthropic 失去领先时仍可继续从 AI 获利。对读者：评估 AI 产业链时，可把「卖铲人」与「淘金者」分开定价，前者现金流确定性更高。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/19/anthropics-ipo-puts-ais-circular-financing-boom-to-the-test/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="黄仁勋离任后-纳德拉仍对-nvidia-保持信心" tabindex="-1">黄仁勋离任后，纳德拉仍对 Nvidia 保持信心 <a class="header-anchor" href="#黄仁勋离任后-纳德拉仍对-nvidia-保持信心" aria-label="Permalink to &quot;黄仁勋离任后，纳德拉仍对 Nvidia 保持信心&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/260961d42e47.webp" alt="配图"></p><p>微软 CEO 纳德拉公开表达对 Nvidia 临时 CEO Colette Kress 的信心，后者在黄仁勋离任后接任。对读者：头部云厂商的公开背书是观察 Nvidia 过渡期稳定性的重要信号，可跟进其下一代产品路线是否如期。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/18/microsoft-ceo-satya-nadella-remains-confident-in-nvidia-after-huangs-exit/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="chatgpt-上线-live-dictation-边说边转写" tabindex="-1">ChatGPT 上线 Live Dictation：边说边转写 <a class="header-anchor" href="#chatgpt-上线-live-dictation-边说边转写" aria-label="Permalink to &quot;ChatGPT 上线 Live Dictation：边说边转写&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/a5b89b366269.jpg" alt="配图"></p><p>OpenAI 为 ChatGPT 推出 Live Dictation，麦克风输入在你说话时即转写为文字，无需等录音结束，并已在所有套餐的网页、桌面端、iOS 与 Android 上全球推送。使用中可点击声波查看实时文本并在提示框中编辑。对读者：语音输入延迟降低后，长提示词场景可优先改用口述，减少打字成本。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1037634/openai-chatgpt-live-dictation" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="canva-新增-ai「关闭」开关" tabindex="-1">Canva 新增 AI「关闭」开关 <a class="header-anchor" href="#canva-新增-ai「关闭」开关" aria-label="Permalink to &quot;Canva 新增 AI「关闭」开关&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/fe80638515f4.png" alt="配图"></p><p>Canva 允许用户关闭生成式 AI 功能，包括 AI 扩图 Magic Expand 和聊天机器人生成图像；但背景移除、Magic Grab 等不生成新内容的工具仍保持开启。对读者：AI 功能开关正成为产品合规与用户信任的标配，设计协作类工具选型时可把「可关闭性」列为评估项。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1037126/canva-ai-features-off-button" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="全美最大学区考虑弃用-google-搜索" tabindex="-1">全美最大学区考虑弃用 Google 搜索 <a class="header-anchor" href="#全美最大学区考虑弃用-google-搜索" aria-label="Permalink to &quot;全美最大学区考虑弃用 Google 搜索&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e9cbfdd31d44.jpg" alt="配图"></p><p>纽约、洛杉矶、芝加哥学区正考虑 Google 替代方案，因 Google 表示退出 AI 功能的学校将无法使用搜索，从明年起学校无法在不关闭 Gemini 功能的情况下单独保留搜索。对读者：教育市场对强制 AI 捆绑的反弹，可能改变校园软件的采购标准，相关供应商需提前准备可分离方案。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1037151/school-districts-ditching-google" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="实测-apple-watch-常听-ai-两周-siri-recap-隐私优先的取舍" tabindex="-1">实测 Apple Watch 常听 AI 两周：Siri Recap 隐私优先的取舍 <a class="header-anchor" href="#实测-apple-watch-常听-ai-两周-siri-recap-隐私优先的取舍" aria-label="Permalink to &quot;实测 Apple Watch 常听 AI 两周：Siri Recap 隐私优先的取舍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/672d6d7e18a2.jpg" alt="配图"></p><p>作者在 Apple Watch Ultra 4 上测试 Siri Recap 与亚马逊 Bee Frontier 约一个月，两者都能环境收音并 AI 摘要，苹果走极简与隐私优先路线，但需明确授权。对读者：可穿戴常听 AI 的差异点在隐私设计而非功能，选型时应优先确认数据留存与授权粒度。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1037100/apple-siri-recap-audio-intelligence-hands-on" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-如何用-performance-factory-让-chatgpt-保持快速" tabindex="-1">OpenAI 如何用 Performance Factory 让 ChatGPT 保持快速 <a class="header-anchor" href="#openai-如何用-performance-factory-让-chatgpt-保持快速" aria-label="Permalink to &quot;OpenAI 如何用 Performance Factory 让 ChatGPT 保持快速&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/548a670be6ac.png" alt="配图"></p><p>OpenAI 介绍 Performance Factory：一套由 Codex 驱动的工作流系统，自动发现并修复性能问题，以维持 ChatGPT 的响应速度。对读者：把编码 Agent 用于自身基础设施的性能治理，是可复用的工程范式，值得在团队内试点自动化性能巡检。</p><p class="news-entry-source"><a href="https://openai.com/index/how-openai-performance-factory-keeps-chatgpt-fast" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google-发布-gemini-4-neon" tabindex="-1">Google 发布 Gemini 4 Neon <a class="header-anchor" href="#google-发布-gemini-4-neon" aria-label="Permalink to &quot;Google 发布 Gemini 4 Neon&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c9b3bddff83c.webp" alt="配图"></p><p>Google 推出 Gemini 4 Neon，面向复杂编码与分析任务提供前沿级智能，同时成本更低。VentureBeat 称其编码性能达到 Opus 5.5 级别，API token 价格低 25%。对读者：若正在为编码 Agent 选型，Neon 值得纳入基准测试，但需先厘清 Gemini 4 系列复杂的定价结构。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/introducing-gemini-4-neon/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="gemini-4-neon-细节-1m-上下文-aa-编码-agent-指数第一" tabindex="-1">Gemini 4 Neon 细节：1M 上下文，AA 编码 Agent 指数第一 <a class="header-anchor" href="#gemini-4-neon-细节-1m-上下文-aa-编码-agent-指数第一" aria-label="Permalink to &quot;Gemini 4 Neon 细节：1M 上下文，AA 编码 Agent 指数第一&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-19">2026-11-19</time></p><p>Gemini 4 Neon 支持 1M 上下文，定价为每百万 token 3 美元输入、15 美元输出，AA 智能指数得分 61，并在 AA 编码 Agent 指数上排名第一。对读者：长上下文加编码 Agent 双料第一，适合评估将其用于大型代码库理解与多步重构任务。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/18/google-gemini-4-neon-release/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="genie-4-开放使用-实时音频与可编辑交互世界" tabindex="-1">Genie 4 开放使用：实时音频与可编辑交互世界 <a class="header-anchor" href="#genie-4-开放使用-实时音频与可编辑交互世界" aria-label="Permalink to &quot;Genie 4 开放使用：实时音频与可编辑交互世界&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/3fd36d2d2927.png" alt="配图"></p><p>Google AI Ultra 订阅用户现可使用 Genie 4，生成带实时音频与编辑能力的交互式世界。对读者：这是世界模型产品化的早期形态，做游戏、仿真或教育内容的团队可申请体验，观察其可控性与生成成本。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/genie-4-is-now-available/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="gemini-应用下探低内存-android-设备" tabindex="-1">Gemini 应用下探低内存 Android 设备 <a class="header-anchor" href="#gemini-应用下探低内存-android-设备" aria-label="Permalink to &quot;Gemini 应用下探低内存 Android 设备&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/65afdf655008.webp" alt="配图"></p><p>Google Gemini 应用现支持低内存 Android 设备，可在手机上使用 Gemini Live 与自定义图像生成。对读者：端侧 AI 的覆盖面向中低端机型延伸，做移动端产品的团队应重新评估低端机上的 AI 功能可用性。</p><p class="news-entry-source"><a href="https://blog.google/innovation-and-ai/products/gemini-app/gemini-lower-memory-devices/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="新-lora-适配器将-qwen3-8-编码成功率从-39-提升到-65" tabindex="-1">新 LoRA 适配器将 Qwen3.8 编码成功率从 39% 提升到 65% <a class="header-anchor" href="#新-lora-适配器将-qwen3-8-编码成功率从-39-提升到-65" aria-label="Permalink to &quot;新 LoRA 适配器将 Qwen3.8 编码成功率从 39% 提升到 65%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-19">2026-11-19</time></p><p>Hugging Face 发布 Qwen3.8-27B-pi-adapted，这是用强化学习为 pi 编码 Agent 训练的 Apache-2.0 LoRA 适配器，SWE-bench Pro hard-51 pass@1 从 39.2% 升至 64.7%，Terminal-Bench 2.1 从 39.5% 升至 55.8%。对读者：小模型加专用适配器可逼近大模型编码表现，预算有限的团队可优先尝试此类开源方案。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/18/hugging-face-qwen3-8-27b-pi-adapted-lora/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="cloudflare-开放-clairic-与-clairic-flash-权重" tabindex="-1">Cloudflare 开放 Clairic 与 Clairic-flash 权重 <a class="header-anchor" href="#cloudflare-开放-clairic-与-clairic-flash-权重" aria-label="Permalink to &quot;Cloudflare 开放 Clairic 与 Clairic-flash 权重&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Cloudflare Blog</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c055b50f9562.png" alt="配图"></p><p>Clairic 从预览转正，Clairic-flash 加入 Workers AI，两款抽取模型均以开放权重形式发布，来自新成立的 Workers AI Superintelligence 团队。对读者：边缘侧信息抽取有了可自托管的开源选项，可评估其在表单、文档解析场景的准确率与延迟。</p><p class="news-entry-source"><a href="https://blog.cloudflare.com/open-clairic/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="daisyrose-27b-推进后训练效率前沿" tabindex="-1">DaisyRose-27B：推进后训练效率前沿 <a class="header-anchor" href="#daisyrose-27b-推进后训练效率前沿" aria-label="Permalink to &quot;DaisyRose-27B：推进后训练效率前沿&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/64aa97a5bad1.webp" alt="配图"></p><p>Hugging Face 上 RadixArk 发布 DaisyRose-27B，聚焦后训练效率的提升。对读者：后训练成本正成为模型落地的关键变量，可关注其训练配方是否可迁移到自有微调流程。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/RadixArk/daisyrose-27b-pushing-the-frontier-of-post-trainin" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="llm-gemini-0-38-发布-适配-gemini-4-neon" tabindex="-1">llm-gemini 0.38 发布，适配 Gemini 4 Neon <a class="header-anchor" href="#llm-gemini-0-38-发布-适配-gemini-4-neon" aria-label="Permalink to &quot;llm-gemini 0.38 发布，适配 Gemini 4 Neon&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/f00222e16928.webp" alt="配图"></p><p>Simon Willison 发布 llm-gemini 0.38，接入今日推出的 Gemini 4 Neon，并吐槽 Gemini 4 系列定价愈发混乱：此前 Hydrogen、Argon、Carbon 三档中 Argon 与 Carbon 同价，Neon 发布材料则直接不提 Argon。对读者：用 LLM 命令行工具接 Gemini 时，务必先核对各档价格与折扣到期时间，避免账单意外。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/18/llm-gemini/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="airbnb-用「每任务成本」运营-bedrock-上的编码-agent" tabindex="-1">Airbnb 用「每任务成本」运营 Bedrock 上的编码 Agent <a class="header-anchor" href="#airbnb-用「每任务成本」运营-bedrock-上的编码-agent" aria-label="Permalink to &quot;Airbnb 用「每任务成本」运营 Bedrock 上的编码 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-11-19">2026-11-19</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/76048d7df4fd.png" alt="配图"></p><p>Airbnb 在真实工程任务上跑评测，并借助 Amazon Bedrock 可观测性为编码 Agent 选模型、控成本；文章说明每任务成本如何指导选型、生产花费为何偏离评测结果，以及如何监控延迟、管理配额与归因开销。对读者：编码 Agent 的成本治理应以任务为单位而非 token，建议先建立每任务成本基线再扩量。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/how-airbnb-uses-cost-per-task-to-operate-coding-agents-on-amazon-bedrock/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="css-scroll-state-查询" tabindex="-1">CSS scroll-state() 查询 <a class="header-anchor" href="#css-scroll-state-查询" aria-label="Permalink to &quot;CSS scroll-state() 查询&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-11-19">2026-11-19</time></p><p>CSS-Tricks 介绍 scroll-state() 查询：它允许根据滚动行为切换所用 CSS，与「边刷边焦虑」的状态无关。对读者：滚动驱动的 UI 效果可少写 JS 监听，建议在目标浏览器支持度确认后用于吸顶、进度提示等场景。</p><p class="news-entry-source"><a href="https://css-tricks.com/almanac/functions/s/scroll-state/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const m=a(i,[["render",s]]);export{g as __pageData,m as default};
